#!/usr/bin/env node
// Generate the web-side network map from networks.json.
//
// One registry, one generated copy. `--check` exits 1 when the committed file
// is stale, so CI can fail instead of letting the two drift.

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { NETWORKS, repoRoot } from "./lib/networks.mjs";

const outPath = path.join(repoRoot, "web", "src", "lib", "networks.generated.ts");

const content = `// Generated by scripts/generate-web-networks.mjs from networks.json.
// Do not edit by hand. Run: node scripts/generate-web-networks.mjs

export const NETWORKS = ${JSON.stringify(NETWORKS, null, 2)} as const;

export type NetworkSlug = keyof typeof NETWORKS;
`;

const check = process.argv.includes("--check");

if (check) {
  const current = existsSync(outPath) ? readFileSync(outPath, "utf8") : "";
  if (current !== content) {
    console.error(
      "networks.generated.ts is stale; run: node scripts/generate-web-networks.mjs",
    );
    process.exit(1);
  }
  console.log("web network map is in sync with networks.json");
} else {
  writeFileSync(outPath, content);
  console.log(`wrote ${path.relative(repoRoot, outPath)}`);
}
